pub enum PtyStatus {
    /// "running"
    Running,
    /// "exited"
    Exited,
}

impl PtyStatus {
    pub const fn as_str(&self) -> &'static str {
        match self {
            Self::Running => "running",
            Self::Exited => "exited",
        }
    }
}

